"use strict";(self.webpackChunk_iehr_web=self.webpackChunk_iehr_web||[]).push([[849],{6164:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"html","value":"<strong>Overview</strong>","className":"sidebar-title"},{"type":"link","label":"Welcome to iEHR","href":"/docs/","docId":"index","unlisted":false},{"type":"link","label":"UDHP","href":"/docs/udhp","docId":"udhp","unlisted":false},{"type":"link","label":"Interoperable","href":"/docs/interoperable","docId":"interoperable","unlisted":false},{"type":"link","label":"AI & Analytics","href":"/docs/ai","docId":"ai","unlisted":false},{"type":"link","label":"Development Toolset","href":"/docs/sdk","docId":"sdk","unlisted":false},{"type":"html","value":"<strong>Integration</strong>","className":"sidebar-title"},{"type":"link","label":"Mapper Agent","href":"/docs/integration/agent","docId":"integration/agent","unlisted":false},{"type":"link","label":"Migrating to iEHR","href":"/docs/integration/migration","docId":"integration/migration","unlisted":false},{"type":"link","label":"Integration","href":"/docs/integration/","docId":"integration/integration","unlisted":false},{"type":"link","label":"HL7 Interfacing","href":"/docs/integration/hl7-interfacing","docId":"integration/hl7-interfacing","unlisted":false},{"type":"link","label":"SMART App Launch","href":"/docs/integration/smart-app-launch","docId":"integration/smart-app-launch","unlisted":false},{"type":"html","value":"<strong>Platform</strong>","className":"sidebar-title"},{"type":"link","label":"Deployment","href":"/docs/platform/deployment","docId":"platform/deployment","unlisted":false},{"type":"link","label":"Authorization and Access Control","href":"/docs/platform/auth","docId":"platform/auth","unlisted":false},{"type":"link","label":"FHIR\xae Datastore","href":"/docs/platform/fhir-datastore","docId":"platform/fhir-datastore","unlisted":false},{"type":"link","label":"Search","href":"/docs/platform/search","docId":"platform/search","unlisted":false},{"type":"link","label":"GraphQL API","href":"/docs/platform/graphql","docId":"platform/graphql","unlisted":false},{"type":"link","label":"FHIRCast","href":"/docs/platform/fhircast","docId":"platform/fhircast","unlisted":false},{"type":"link","label":"Agents and Bots","href":"/docs/platform/bots","docId":"platform/bots","unlisted":false},{"type":"link","label":"Subscriptions","href":"/docs/platform/subscriptions","docId":"platform/subscriptions","unlisted":false}]},"docs":{"ai":{"id":"ai","title":"AI & Analytics","description":"The iEHR platform leverages advanced AI and analytics tools to transform healthcare data into actionable insights. Ensuring data quality and integrity is critical for generating meaningful, accurate reports and improving decision-making processes. Continuous monitoring of data quality plays a key role in maintaining these standards.","sidebar":"docsSidebar"},"index":{"id":"index","title":"Welcome to iEHR","description":"The iEHR.ai platform is a AI-driven, FHIR\xae-native Unified Digital Health Platform (UDHP) that represents a transformative shift in healthcare technology. Unlike traditional, monolithic Electronic Health Records (EHRs), iEHR.ai embraces a modern, ecosystem-based approach that prioritizes interoperability, modularity, and innovation.","sidebar":"docsSidebar"},"integration/agent":{"id":"integration/agent","title":"Mapper Agent","description":"The Mapper Agent operates within your organization\'s firewall, serving as a critical bridge between your healthcare infrastructure and a variety of medical devices. It facilitates seamless integration by utilizing low-level communication protocols such as HL7/MLLP, ASTM, and DICOM. While these protocols are essential for device compatibility and data exchange, their lack of encryption presents potential security vulnerabilities that need to be addressed.","sidebar":"docsSidebar"},"integration/hl7-interfacing":{"id":"integration/hl7-interfacing","title":"HL7 Interfacing","description":"The iEHR platform provides a powerful and highly customizable HL7 interfacing engine, designed as a robust alternative to solutions like Mirth or Corepoint. This engine enables developers to produce and consume HL7 feeds from a wide range of legacy healthcare applications, such as EHRs, LIS, RIS/PACS, billing systems, and more.","sidebar":"docsSidebar"},"integration/integration":{"id":"integration/integration","title":"Integration","description":"The iEHR platform offers a suite of powerful integration capabilities, making it one of the most valued features of the system. These capabilities empower developers to create robust and effective connections across healthcare systems. iEHR supports three primary types of integrations:","sidebar":"docsSidebar"},"integration/migration":{"id":"integration/migration","title":"Migrating to iEHR","description":"Migrating to iEHR requires planning and execution to ensure a smooth transition from your existing digital healthcare platform. This guide provides an in-depth look at the best practices for migrating data to iEHR with minimal service interruptions and no performance degradation.","sidebar":"docsSidebar"},"integration/smart-app-launch":{"id":"integration/smart-app-launch","title":"SMART App Launch","description":"The iEHR platform supports SMART App Launch, allowing seamless integration and testing of healthcare applications. This feature empowers developers to securely link their apps with iEHR and other healthcare systems, enabling efficient workflows and interoperability.","sidebar":"docsSidebar"},"interoperable":{"id":"interoperable","title":"Interoperable","description":"The iEHR platform leverages the FHIR\xae (Fast Healthcare Interoperability Resources) standard to store and manage healthcare data, providing a wide range of benefits that enhance system interoperability and future readiness.","sidebar":"docsSidebar"},"platform/auth":{"id":"platform/auth","title":"Authorization and Access Control","description":"The iEHR platform ensures compliance and seamless integration through its versatile authentication and authorization configurations. By leveraging multiple methods and tools, iEHR enables secure verification of user identity and fine-grained control over data access.","sidebar":"docsSidebar"},"platform/bots":{"id":"platform/bots","title":"Agents and Bots","description":"Agents and Bots are intelligent, event-driven automation components designed to orchestrate and optimize healthcare workflows across the Unified Digital Health Platform. These modular tools are purpose-built for healthcare, leveraging FHIR\xae Subscriptions to trigger actions in real time. Maestro Agents coordinate complex tasks, while Bots execute specific functions\u2014together forming the backbone of seamless integration and automation within iEHR.ai.","sidebar":"docsSidebar"},"platform/deployment":{"id":"platform/deployment","title":"Deployment","description":"iEHR is designed for seamless deployment through Infrastructure as Code (IaC) frameworks. These frameworks include compatibility with Microsoft, Amazon, Google, and on-premises servers.","sidebar":"docsSidebar"},"platform/fhir-datastore":{"id":"platform/fhir-datastore","title":"FHIR\xae Datastore","description":"The iEHR FHIR\xae Datastore is a comprehensive platform designed to manage healthcare data efficiently and securely. Supporting all CRUD operations (Create, Read, Update, Delete) on FHIR\xae resources, it goes beyond the basics with features for data validation, modeling, bot execution, analytics, and more. If you\'re new to FHIR\xae, you can explore the FHIR\xae Basics documentation.","sidebar":"docsSidebar"},"platform/fhircast":{"id":"platform/fhircast","title":"FHIRCast","description":"FHIRCast is an experimental feature within the iEHR platform, currently in early alpha development. It supports FHIRCast STU3, enabling real-time synchronization across healthcare applications for enhanced collaboration and interoperability.","sidebar":"docsSidebar"},"platform/graphql":{"id":"platform/graphql","title":"GraphQL API","description":"The iEHR platform provides a robust GraphQL API, enabling developers to efficiently interact with FHIR\xae resources. With its flexibility and power, the API facilitates creating, updating, and searching healthcare data to support the development of advanced healthcare applications.","sidebar":"docsSidebar"},"platform/search":{"id":"platform/search","title":"Search","description":"The iEHR platform offers advanced search capabilities to efficiently query and retrieve FHIR\xae resources, ensuring robust handling of complex queries and supporting diverse filtering and sorting mechanisms. This functionality is optimized for healthcare applications that demand precision and scalability.","sidebar":"docsSidebar"},"platform/subscriptions":{"id":"platform/subscriptions","title":"Subscriptions","description":"Subscriptions in iEHR are event-driven mechanisms, similar to webhooks, that play a vital role in enabling integrations and automations. By subscribing to changes on FHIR\xae resources, iEHR facilitates real-time updates, ensuring efficient and seamless workflows. For an in-depth description of FHIR\xae Subscriptions, refer to the HL7.org documentation.","sidebar":"docsSidebar"},"policies/Applications-and-Data-Criticality-Analysis":{"id":"policies/Applications-and-Data-Criticality-Analysis","title":"Applications and Data Criticality Analysis","description":"Purpose"},"policies/Breach-Training-for-Employees":{"id":"policies/Breach-Training-for-Employees","title":"HIPAA Security, Privacy and Breach Notification Training","description":"It is the policy of iEHR that all employees will access, use and disclose PHI only as permitted under HIPAA, and that all employees shall be vigilant with respect to guarding PHI. However, in the event that a potential breach of unsecured PHI occurs, the following policies and procedures shall be followed."},"policies/Configuration-Change-Policy":{"id":"policies/Configuration-Change-Policy","title":"Configuration Change Policy","description":"Purpose"},"policies/Contingency-Plan":{"id":"policies/Contingency-Plan","title":"Contingency Plan","description":"Purpose"},"policies/Data-Backup-Policy":{"id":"policies/Data-Backup-Policy","title":"Data Backup Policy","description":"Purpose"},"policies/Emergency-Plan-Testing-Policy-and-Procedure":{"id":"policies/Emergency-Plan-Testing-Policy-and-Procedure","title":"Emergency Testing Policy and Procedure","description":"Purpose"},"policies/Evaluation-Policy":{"id":"policies/Evaluation-Policy","title":"Evaluation Policy","description":"Purpose"},"policies/Facility-Access-Controls-Policy":{"id":"policies/Facility-Access-Controls-Policy","title":"Facility Access Controls Policy and Procedure","description":"PurposeiEHR"},"policies/index":{"id":"policies/index","title":"Risk Assessment, Policies and Procedures","description":"1.  Applications-and-Data-Criticality-Analysis"},"policies/Information-System-Activity-Review-Policy":{"id":"policies/Information-System-Activity-Review-Policy","title":"Information System Activity Review Policy","description":"Policy"},"policies/Integrity-Controls-Policy":{"id":"policies/Integrity-Controls-Policy","title":"Integrity Controls Policy","description":"PURPOSE"},"policies/Internet-and-Email-Use-Policy":{"id":"policies/Internet-and-Email-Use-Policy","title":"Internet and Email Use Policy","description":"PURPOSE"},"policies/IT-System-Maintenance-Policy":{"id":"policies/IT-System-Maintenance-Policy","title":"IT System Maintenance Policy","description":"Purpose"},"policies/Media-Sanitization-and-Disposal-Policy":{"id":"policies/Media-Sanitization-and-Disposal-Policy","title":"Media Sanitization and Disposal Policy","description":"PURPOSE"},"policies/Mobile-Devices-Policy":{"id":"policies/Mobile-Devices-Policy","title":"Mobile Devices Policy","description":"Purpose"},"policies/Paper-Sanitization-Policy":{"id":"policies/Paper-Sanitization-Policy","title":"Paper Destruction Policy","description":"Purpose"},"policies/Password-Policy":{"id":"policies/Password-Policy","title":"Password Policy","description":"Purpose"},"policies/Patch-Management-Policy":{"id":"policies/Patch-Management-Policy","title":"Patch Management Policy","description":"Overview"},"policies/Person-or-Entity-Authentication":{"id":"policies/Person-or-Entity-Authentication","title":"Person or Entity Authentication","description":"PURPOSE"},"policies/Protection-from-Malicious-Software-Policy":{"id":"policies/Protection-from-Malicious-Software-Policy","title":"Protection from Malicious Software Policy","description":"BACKGROUND"},"policies/Remote-Access-Policy":{"id":"policies/Remote-Access-Policy","title":"Remote Access Policy and Procedure","description":"Purpose"},"policies/Risk-Management-Policy":{"id":"policies/Risk-Management-Policy","title":"Risk Management Process Policy","description":"Purpose"},"policies/Security-Awareness-Training-Policy":{"id":"policies/Security-Awareness-Training-Policy","title":"Security Awareness Program Training Policy","description":"Overview"},"policies/Security-Incident-Response-Plan":{"id":"policies/Security-Incident-Response-Plan","title":"Security Incident Response Plan","description":"Purpose"},"policies/Security-Program-for-Security-Officer":{"id":"policies/Security-Program-for-Security-Officer","title":"HIPAA Security Program Policy and Procedures for Security Officer","description":"Purpose"},"policies/Technical-Safeguards-Access-Control-Policy":{"id":"policies/Technical-Safeguards-Access-Control-Policy","title":"Technical Safeguards- Access Control Policy","description":"ScopeiEHR company and workforce."},"policies/Termination-Policy":{"id":"policies/Termination-Policy","title":"Termination Policy","description":"Purpose"},"policies/Transmission-Security-Policy":{"id":"policies/Transmission-Security-Policy","title":"Transmission Security Policy","description":"Purpose"},"policies/Uses-and-Disclosures-of-PHI":{"id":"policies/Uses-and-Disclosures-of-PHI","title":"Uses and Disclosures of Protected Health Information","description":"Purpose"},"policies/Violation-Sanction-Policy":{"id":"policies/Violation-Sanction-Policy","title":"Violation Sanction Policy","description":"PURPOSE"},"policies/Wireless-Security-Policy":{"id":"policies/Wireless-Security-Policy","title":"Wireless Security Policy","description":"PURPOSE"},"policies/Workstation-Security-Policy":{"id":"policies/Workstation-Security-Policy","title":"Workstation Security Policy","description":"Purpose"},"sdk":{"id":"sdk","title":"Development Toolset","description":"The iEHR FHIR Framework is a comprehensive toolset specifically designed to simplify the development of healthcare applications on the iEHR platform. Although the FHIR\xae standard is powerful, its API can be complex and requires a significant learning curve. The framework empowers developers to overcome these challenges with ease.","sidebar":"docsSidebar"},"udhp":{"id":"udhp","title":"UDHP","description":"Unified Digital Health Platform (UDHP) represents a transformative shift in healthcare technology. Rather than relying on fragmented systems and siloed data, UDHPs offer a cohesive, interoperable architecture that integrates electronic health records (EHRs), clinical workflows, analytics, and patient engagement tools into a single, unified ecosystem.","sidebar":"docsSidebar"},"workflows/administration-provider-directory":{"id":"workflows/administration-provider-directory","title":"Provider Directory","description":"Provider directories are essential databases that house critical information about healthcare providers, ranging from individual practitioners to entire organizations. Accurate and standardized modeling of these directories ensures a better patient experience through improved coordination of care and operational efficiency. This section provides a series of guides on how to properly model your organization\'s provider directory, focusing on key challenges:"},"workflows/billing":{"id":"workflows/billing","title":"Billing and Payments","description":"In iEHR, billing and payments are seamlessly integrated into the healthcare workflow. For instance, after a lab test is completed, a DiagnosticReport is generated and, along with related resources, is automatically sent to the billing system once the report is finalized."},"workflows/careplans":{"id":"workflows/careplans","title":"Care Plans","description":"Care Plans are essential tools in healthcare, representing protocols that patients should follow. They exist in two forms:"},"workflows/charting":{"id":"workflows/charting","title":"Charting","description":"Building a comprehensive charting experience in iEHR involves integrating multiple FHIR\xae resources to meet the needs of healthcare practitioners. Here are the primary interactions to consider when developing a custom charting interface:"},"workflows/communications":{"id":"workflows/communications","title":"Messaging & Communications","description":"FHIR\xae supports messaging workflows through the Communication resource, allowing your system to manage message content and metadata independently of the medium (email, SMS, chat, etc.). These Communications can be structured to support various use cases, including:"},"workflows/labs-imaging":{"id":"workflows/labs-imaging","title":"Labs & Imaging","description":"The iEHR platform provides comprehensive support for managing lab and imaging orders, results, and related data. Here\u2019s aN overview of the key resources and code systems involved:"},"workflows/medications":{"id":"workflows/medications","title":"Medications","description":"In the iEHR platform, representing medications using FHIR\xae (Fast Healthcare Interoperability Resources) supports a variety of common scenarios and can be integrated with Bots to enable complex medication-related workflows. Here\u2019s a guide to understanding and utilizing medication resources in iEHR:"},"workflows/questionnaires":{"id":"workflows/questionnaires","title":"Questionnaires & Assessments","description":"Creating, updating, and embedding FHIR\xae Questionnaires for both patients and practitioners is a common use case for iEHR. The platform supports a variety of features to ensure that questionnaires are versatile and easy to use."},"workflows/scheduling":{"id":"workflows/scheduling","title":"Scheduling","description":"Scheduling is a fundamental workflow in iEHR, supporting a wide range of complex scheduling needs through the correct use of the FHIR\xae specification. This guide provides a comprehensive overview of the key resources and workflows involved in managing scheduling within the iEHR platform."}}}}')}}]);